import { fork } from "node:child_process";
import { randomUUID } from "node:crypto";
import { mkdir, readFile, rename, unlink, writeFile } from "node:fs/promises";
import { dirname } from "node:path";
import { fileURLToPath } from "node:url";
import { connect } from "node:net";

const starts = new Map();
const read = async (file) => JSON.parse(await readFile(file, "utf8").catch(() => "null"));
const ownerAlive = (pid) => { if (!Number.isSafeInteger(pid) || pid <= 0) return false; try { process.kill(pid, 0); return true; } catch (error) { return error.code === "EPERM"; } };
const removeOwnRecord = async (file, id) => { if ((await read(file))?.id === id) await unlink(file).catch(() => {}); };
const portOccupied = (endpoint) => new Promise((resolve) => {
  const url = new URL(endpoint);
  const socket = connect({ host: url.hostname, port: Number(url.port || (url.protocol === "https:" ? 443 : 80)) });
  const finish = (value) => { socket.destroy(); resolve(value); };
  socket.once("connect", () => finish(true));
  socket.once("error", () => finish(false));
  socket.setTimeout(1_000, () => finish(true));
});
const command = async (record, action) => {
  const url = new URL(record.controlUrl);
  if (url.protocol !== "http:" || url.hostname !== "127.0.0.1") throw new Error("本地 H3 管理地址无效");
  const response = await fetch(`${url.origin}/${action}`, {
    method: action === "status" ? "GET" : "POST",
    headers: { Authorization: `Bearer ${record.token}` },
    signal: AbortSignal.timeout(action === "stop" ? 18_000 : 2_000),
  });
  const payload = await response.json();
  if (!response.ok || payload.sessionId !== record.id || payload.endpoint !== record.endpoint) throw new Error(payload.message || "本地 H3 管理会话不匹配");
  return payload;
};

export const inspectH3ManagedSession = async (file, endpoint) => {
  const record = await read(file);
  if (!record) return { started: false, pid: 0 };
  if (record.endpoint !== endpoint) return { started: false, conflict: true, reason: "另一地址的本地 H3 会话尚未停止，请返回该配置停止后再启动" };
  if (!record.controlUrl) return { started: false, starting: ownerAlive(record.ownerPid), reason: "本地 H3 控制服务正在启动" };
  try { return await command(record, "status"); }
  catch { return { started: false, uncertain: ownerAlive(record.ownerPid), reason: "本地 H3 控制连接不可达，尚不能确认运行状态" }; }
};

export const launchH3ManagedSession = (file, { endpoint, command: launchCommand, cwd }) => {
  if (starts.has(file)) return starts.get(file);
  const operation = (async () => {
    await mkdir(dirname(file), { recursive: true });
    const previous = await read(file);
    if (previous) {
      const existing = await inspectH3ManagedSession(file, endpoint);
      if (existing.started) return existing;
      if (existing.conflict || existing.starting || existing.uncertain) throw new Error(existing.reason);
      // A dead controller is never adopted by PID, and no unrelated process is killed.
      if (ownerAlive(previous.ownerPid)) {
        await command(previous, "stop");
      }
      await removeOwnRecord(file, previous.id);
    }
    if (await portOccupied(endpoint)) throw new Error("本地 H3 端口已被其他进程使用；不会接管或停止用户自行启动的服务");
    const record = { id: randomUUID(), token: randomUUID(), endpoint, ownerPid: process.pid };
    try { await writeFile(file, JSON.stringify(record), { flag: "wx", mode: 0o600 }); }
    catch (error) { if (error.code === "EEXIST") throw new Error("本地 H3 正在由另一请求启动，请稍后查看状态"); throw error; }
    let host;
    try {
      host = fork((await import('../../../core/src/native-extensions.mjs')).nativeExtensionResource(fileURLToPath(new URL("./local-h3-process-host.mjs", import.meta.url))), [], {
        windowsHide: true, stdio: ["ignore", "ignore", "ignore", "ipc"],
        env: { ...process.env, ELECTRON_RUN_AS_NODE: "1" }, execArgv: [],
      });
      const result = await new Promise((resolve, reject) => {
        const timeout = setTimeout(() => reject(new Error("本地 H3 控制服务启动超时")), 10_000);
        const finish = (error, value) => { clearTimeout(timeout); error ? reject(error) : resolve(value); };
        host.once("error", (error) => finish(error));
        host.once("exit", () => finish(new Error("本地 H3 控制服务提前退出")));
        host.once("message", (value) => finish(value.error ? new Error(value.error) : null, value));
        host.send({ ...record, command: launchCommand, cwd });
      });
      const next = `${file}.${record.id}.next`;
      await writeFile(next, JSON.stringify({ ...record, controlUrl: result.controlUrl }), { mode: 0o600 });
      await rename(next, file);
      host.once("exit", () => { void removeOwnRecord(file, record.id); });
      // Keep the IPC channel for parent-exit cleanup, but not the main event loop.
      host.unref();
      host.channel?.unref();
      return result;
    } catch (error) {
      if (host?.connected) host.disconnect();
      await removeOwnRecord(file, record.id);
      throw error;
    }
  })().finally(() => starts.delete(file));
  starts.set(file, operation);
  return operation;
};

export const stopH3ManagedSession = async (file, endpoint) => {
  // A stop during launch waits only for the bounded supervisor handshake.
  await starts.get(file)?.catch(() => {});
  const record = await read(file);
  if (!record) return { started: false, stopped: true };
  if (record.endpoint !== endpoint) throw new Error("本地 H3 管理会话地址不匹配，已拒绝停止其他配置的进程");
  if (!record.controlUrl) throw new Error("本地 H3 控制服务正在启动，请稍后重试停止");
  const result = await command(record, "stop");
  if (result.started || !result.stopped) throw new Error("本地 H3 尚未确认停止");
  await removeOwnRecord(file, record.id);
  return result;
};

// A lightweight supervisor, not the inference service. IPC disconnect means
// Shensi has exited: only the process tree started here is then terminated.
import { spawn } from "node:child_process";
import { createServer } from "node:http";
import { timingSafeEqual } from "node:crypto";

let child;
let server;
let session;
let stopping;
let failure = "";
let diagnostics = '';
const recordOutput = chunk => { diagnostics = (diagnostics + String(chunk)).slice(-12000).replace(/Bearer\s+\S+|\b(?:sk|api)[-_][\w-]{12,}/gi, '[已隐藏]'); };
const alive = () => Boolean(child?.pid && child.exitCode === null && !child.signalCode);
const delay = (ms) => new Promise((resolve) => setTimeout(resolve, ms));
const state = () => ({ sessionId: session.id, endpoint: session.endpoint, started: alive(), pid: alive() ? child.pid : 0, failure, diagnostics });

const stop = () => stopping ||= (async () => {
  if (!alive()) return;
  if (process.platform === "win32") {
    await new Promise((resolve, reject) => {
      const killer = spawn("taskkill.exe", ["/PID", String(child.pid), "/T", "/F"], { windowsHide: true, stdio: "ignore" });
      const timeout = setTimeout(() => { killer.kill(); reject(new Error("停止本地 H3 进程树超时")); }, 10_000);
      killer.once("error", (error) => { clearTimeout(timeout); reject(error); });
      killer.once("close", (code) => { clearTimeout(timeout); code === 0 || !alive() ? resolve() : reject(new Error(`本地 H3 进程树未停止（${code}）`)); });
    });
  } else {
    try { process.kill(-child.pid, "SIGTERM"); } catch (error) { if (error.code !== "ESRCH") throw error; }
  }
  const deadline = Date.now() + 5_000;
  while (alive() && Date.now() < deadline) await delay(50);
  if (alive()) throw new Error("本地 H3 尚未退出，不能确认资源已释放");
})().catch((error) => { stopping = null; throw error; });

const shutdown = async () => {
  try { await stop(); server?.close(); process.exit(0); }
  catch (error) { failure = error.message; process.exitCode = 1; }
};
process.once("disconnect", shutdown);
process.once("SIGTERM", shutdown);
process.once("SIGINT", shutdown);

process.once("message", async (message) => {
  session = message;
  try {
    if (!process.connected) throw new Error("神思控制连接已关闭");
    const expected = Buffer.from(session.token);
    server = createServer(async (request, response) => {
      const supplied = Buffer.from(String(request.headers.authorization || "").replace(/^Bearer /u, ""));
      const json = (code, value) => { response.writeHead(code, { "Content-Type": "application/json", "Cache-Control": "no-store" }); response.end(JSON.stringify(value)); };
      if (supplied.length !== expected.length || !timingSafeEqual(supplied, expected)) return json(403, { message: "Invalid managed session" });
      if (request.method === "GET" && request.url === "/status") return json(200, state());
      if (request.method === "POST" && request.url === "/stop") {
        try {
          await stop();
          json(200, { ...state(), stopped: true });
          server.close(() => process.exit(0));
        } catch (error) { json(500, { ...state(), message: error.message }); }
        return;
      }
      json(404, { message: "Not found" });
    });
    await new Promise((resolve, reject) => { server.once("error", reject); server.listen(0, "127.0.0.1", resolve); });
    const [executable, ...args] = session.command;
    child = spawn(executable, args, { cwd: session.cwd, env: {...process.env,PYTHONUNBUFFERED:'1'}, windowsHide: true, stdio: ['ignore','pipe','pipe'], detached: process.platform !== "win32" });
    child.stdout.on('data',recordOutput);child.stderr.on('data',recordOutput);
    child.once('exit',(code,signal)=>{if(!stopping)failure='进程退出：'+(signal||code);});
    child.once("error", (error) => { failure = error.message; });
    await new Promise((resolve, reject) => { child.once("spawn", resolve); child.once("error", reject); });
    if (!process.connected) return shutdown();
    process.send({ ...state(), controlUrl: `http://127.0.0.1:${server.address().port}` });
  } catch (error) {
    failure = error.message;
    if (process.connected) process.send({ error: failure });
    await shutdown();
  }
});

import { createHash } from "node:crypto";
import { spawn } from "node:child_process";
import { cp, mkdir, open, readFile, readdir, rename, rm, stat, writeFile } from "node:fs/promises";
import { homedir } from "node:os";
import { dirname, extname, join } from "node:path";
import { randomUUID } from "node:crypto";
import { inspectH3ManagedSession, launchH3ManagedSession, stopH3ManagedSession } from "./local-h3-managed-session.mjs";

const RELEASE = Object.freeze({
  repository: "wu798998264-crypto/shensi-local-h3",
  tag: "v0.1.1",
  manifestUrl: "https://raw.githubusercontent.com/wu798998264-crypto/shensi-local-h3/v0.1.1/manifest.json",
  manifestSha256: "6a8c6d1b67d78a3e4749c03b1adb567fcb504eb9dcf78ab7d90a095d93cabc12",
});

const jobs = new Map();

const localDataRoot = () => String(process.env.SHENSI_LOCAL_H3_ROOT || join(process.env.LOCALAPPDATA || join(homedir(), "AppData", "Local"), "Shensi", "runtimes", "local-h3")).trim();
const runtimeRoot = () => join(localDataRoot(), RELEASE.tag);
const installJobFile = () => join(localDataRoot(), "install-job.json");
const runtimeFile = () => join(runtimeRoot(), "runtime.json");
const workflowFile = () => join(runtimeRoot(), "workflow.json");
const sessionFile = () => join(runtimeRoot(), "managed-session.json");
const text = (value, fallback = "") => String(value ?? fallback).trim();
const sha256 = (buffer) => createHash("sha256").update(buffer).digest("hex");
const loopbackUrl = (value) => {
  const raw = text(value, "http://127.0.0.1:8188");
  let parsed;
  try { parsed = new URL(raw); } catch { throw new Error("本地 H3 地址无效"); }
  if (!/^https?:$/u.test(parsed.protocol) || !["127.0.0.1", "localhost", "::1"].includes(parsed.hostname)) throw new Error("本地 H3 只允许连接本机地址");
  return parsed.origin;
};
const jsonFetch = async (url, options = {}, timeoutMs = 5_000) => {
  const response = await fetch(url, { ...options, signal: AbortSignal.timeout(timeoutMs) });
  const raw = await response.text();
  let payload = {};
  try { payload = raw ? JSON.parse(raw) : {}; } catch { payload = { raw }; }
  if (!response.ok) {
    const error = new Error(payload?.error?.message || payload?.message || `本地 H3 返回 HTTP ${response.status}`);
    error.providerErrorCode = `LOCAL_H3_HTTP_${response.status}`;
    throw error;
  }
  return payload;
};

const readJson = async (path) => JSON.parse(await readFile(path, "utf8"));
const persistJob = async (job) => {
  await mkdir(dirname(installJobFile()), { recursive: true });
  await writeFile(installJobFile(), `${JSON.stringify(job, null, 2)}\n`, "utf8");
};
const findFile = async (root, expected) => {
  for (const entry of await readdir(root, { withFileTypes: true }).catch(() => [])) {
    const path = join(root, entry.name);
    if (entry.isFile() && entry.name.toLowerCase() === expected.toLowerCase()) return path;
    if (entry.isDirectory()) {
      const found = await findFile(path, expected);
      if (found) return found;
    }
  }
  return "";
};

export const localH3Release = () => ({ ...RELEASE });
export const localH3RuntimeRoot = () => runtimeRoot();

export const readLocalH3Runtime = async () => {
  const runtime = await readJson(runtimeFile()).catch(() => null);
  if (!runtime || runtime.version !== RELEASE.tag) return null;
  return runtime;
};

const runtimeEndpoint = (settings, runtime) => loopbackUrl(settings?.baseUrl || runtime?.baseUrl || "http://127.0.0.1:8188");
const runtimeComplete = (runtime) => Boolean(runtime?.managedByShensi === true
  && runtime.requiresExternalRuntime !== true && Array.isArray(runtime.launch?.command) && runtime.launch.command.length);
const requiredNodeTypes = ["UNETLoader", "CLIPLoader", "MiniMaxH3ReferenceToVideo", "CreateVideo", "SaveVideo"];

export const probeLocalH3Runtime = async ({ settings = {}, start = false } = {}) => {
  const runtime = await readLocalH3Runtime();
  const endpoint = runtimeEndpoint(settings, runtime);
  const session = await inspectH3ManagedSession(sessionFile(), endpoint);
  const started = session.started === true;
  const reasons = [];
  if (!runtime) reasons.push("尚未装配本地 H3 运行时");
  if (runtime && runtime.managedByShensi !== true) reasons.push("运行时不是由神思装配，已拒绝连接");
  if (runtime && !runtimeComplete(runtime)) reasons.push("当前装配包仅含 H3 适配器，缺少完整推理环境、模型或启动命令，不能用于本地生成");
  if (session.reason) reasons.push(session.reason);
  if (session.failure) reasons.push(`本地 H3 进程失败：${session.failure}`);
  const hasWorkflow = Boolean(await stat(workflowFile()).catch(() => null));
  if (runtime && !hasWorkflow) reasons.push("本地 H3 固定工作流不存在");
  let workflow = null;
  if (hasWorkflow) workflow = await readJson(workflowFile()).catch(() => null);
  const workflowTypes = new Set(Object.values(workflow || {}).map((node) => text(node?.class_type)));
  for (const required of requiredNodeTypes) {
    if (!workflowTypes.has(required)) reasons.push(`固定工作流缺少节点：${required}`);
  }
  let system = null;
  let objectInfo = null;
  if (!started) reasons.push("本地 H3 尚未启动，请先点击启动");
  if (started) {
    try { system = await jsonFetch(`${endpoint}/system_stats`, {}, 4_000); } catch (error) { reasons.push(`ComfyUI 未就绪：${error.message}`); }
  }
  if (system) {
    try { objectInfo = await jsonFetch(`${endpoint}/object_info`, {}, 8_000); } catch (error) { reasons.push(`ComfyUI 节点目录读取失败：${error.message}`); }
  }
  const objectTypes = new Set(Object.keys(objectInfo || {}));
  for (const required of requiredNodeTypes) {
    if (objectInfo && !objectTypes.has(required)) reasons.push(`ComfyUI 缺少节点：${required}`);
  }
  const ready = Boolean(started && runtimeComplete(runtime) && hasWorkflow && system && objectInfo
    && requiredNodeTypes.every((required) => workflowTypes.has(required) && objectTypes.has(required)));
  return {
    available: ready,
    installed: runtimeComplete(runtime) && hasWorkflow,
    adapterInstalled: Boolean(runtime),
    started,
    pid: session.pid || 0,
    uncertain: session.uncertain === true,
    starting: session.starting === true,
    diagnostics: session.diagnostics || '',
    ready,
    endpoint,
    version: runtime?.version || RELEASE.tag,
    workflowVersion: runtime?.workflowVersion || "",
    system,
    hasWorkflow,
    models: ready ? ["minimax-h3-reference-video"] : [],
    reasons,
    installable: !runtimeComplete(runtime),
  };
};

const waitForReady = async (settings, timeoutMs = 60_000) => {
  const startedAt = Date.now();
  while (Date.now() - startedAt < timeoutMs) {
    const probe = await probeLocalH3Runtime({ settings, start: false });
    if (probe.ready) return probe;
    await new Promise((resolve) => setTimeout(resolve, 750));
  }
  return probeLocalH3Runtime({ settings, start: false });
};

export const ensureLocalH3Runtime = async ({ settings = {}, timeoutMs = 60_000 } = {}) => {
  const probe = await probeLocalH3Runtime({ settings, start: false });
  if (probe.ready) return probe;
  const runtime = await readLocalH3Runtime();
  if (!runtime) throw Object.assign(new Error("本地 H3 尚未装配，请先点击“一键装配本地 H3”"), { providerErrorCode: "LOCAL_H3_NOT_INSTALLED" });
  if (!probe.installed) throw Object.assign(new Error(probe.reasons.join("；")), { providerErrorCode: "LOCAL_H3_RUNTIME_INCOMPLETE" });
  if (!probe.started) throw Object.assign(new Error("本地 H3 尚未启动，请先点击“启动本地 H3”"), { providerErrorCode: "LOCAL_H3_NOT_STARTED" });
  if (!probe.ready) throw Object.assign(new Error(`本地 H3 运行时尚未就绪：${probe.reasons.join("；") || "请检查 ComfyUI、模型和端口"}`), { providerErrorCode: "LOCAL_H3_NOT_READY" });
  return probe;
};

export const startLocalH3Runtime = async ({ settings = {}, timeoutMs = 0 } = {}) => {
  const runtime = await readLocalH3Runtime();
  if (!runtime) throw Object.assign(new Error("本地 H3 尚未装配，请先点击“一键装配本地 H3”"), { providerErrorCode: "LOCAL_H3_NOT_INSTALLED" });
  if (!runtimeComplete(runtime)) throw Object.assign(new Error("H3 装配不完整：当前包仅含适配器，没有可启动的本地推理环境"), { providerErrorCode: "LOCAL_H3_RUNTIME_INCOMPLETE" });
  const endpoint = runtimeEndpoint(settings, runtime);
  await launchH3ManagedSession(sessionFile(), { endpoint, command: runtime.launch.command.map(String), cwd: runtime.root || runtimeRoot() });
  return timeoutMs > 0
    ? waitForReady({ ...settings, baseUrl: endpoint }, Math.min(timeoutMs, 60_000))
    : probeLocalH3Runtime({ settings });
};

export const stopLocalH3Runtime = async ({ settings = {} } = {}) => {
  const runtime = await readLocalH3Runtime();
  if (!runtime) return { installed: false, started: false, stopped: false, message: "本地 H3 尚未装配" };
  await stopH3ManagedSession(sessionFile(), runtimeEndpoint(settings, runtime));
  return { installed: runtimeComplete(runtime), started: false, stopped: true, ready: false, available: false, message: "本地 H3 已停止，已释放受管理的后台进程" };
};

const downloadBytes = async (url, onProgress) => {
  const response = await fetch(url, { redirect: "follow", signal: AbortSignal.timeout(15 * 60_000) });
  if (!response.ok || !response.body) throw new Error(`本地 H3 下载失败（HTTP ${response.status || "?"}）`);
  const length = Number(response.headers.get("content-length") || 0);
  const chunks = [];
  let received = 0;
  const reader = response.body.getReader();
  while (true) {
    const chunk = await reader.read();
    if (chunk.done) break;
    const buffer = Buffer.from(chunk.value || []);
    chunks.push(buffer);
    received += buffer.length;
    onProgress?.(length ? received / length : 0);
  }
  return Buffer.concat(chunks);
};

export const startLocalH3Install = async () => {
  const existing = await readLocalH3Runtime();
  if (runtimeComplete(existing)) return { ok: true, alreadyInstalled: true, stage: "complete", percent: 100, message: "本地 H3 运行时已装配；点击启动后才会运行" };
  const active = [...jobs.values()].find((job) => !["complete", "failed"].includes(job.stage));
  if (active) return { ok: true, jobId: active.id, ...active };
